<?php
if(!isset($c,$usuario)||$usuario['rol']!=='CLIENTE'){http_response_code(403);exit;}
$filtroValido=true;
try{$pagina=filter_var($_GET['pagina']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]])?:1;$d=$c->historial($_GET,$pagina);}
catch(DomainException $e){echo '<p class="alerta alerta-error">'.h($e->getMessage()).'</p>'; $filtroValido=false;$d=['filtros'=>CajeroController::filtrosCuenta([], $cuenta['numero']),'filas'=>[],'total'=>0,'pagina'=>1,'paginas'=>1];}
$f=$d['filtros'];$params=array_intersect_key($f,array_flip(['cuenta','tipo','desde','hasta']));
?>
<section class="crud-contenedor"><form method="get" action="<?=h(enlace())?>" class="crud-buscador crud-filtros"><input type="hidden" name="vista" value="movimientos"><div class="crud-campo-busqueda"><label for="cuenta">Cuenta validada</label><input id="cuenta" name="cuenta" value="<?=h($cuenta['numero'])?>" readonly></div><div class="crud-campo-busqueda"><label for="tipo">Tipo</label><select id="tipo" name="tipo"><option value="">Todos</option><?php foreach(MovimientoAdministrativo::TIPOS as $t):?><option value="<?=h($t)?>" <?=$f['tipo']===$t?'selected':''?>><?=h(tipo($t))?></option><?php endforeach;?></select></div><?php foreach(['desde'=>'Desde','hasta'=>'Hasta'] as $k=>$label):?><div class="crud-campo-busqueda"><label for="<?=$k?>"><?=$label?></label><input type="date" id="<?=$k?>" name="<?=$k?>" value="<?=h($f[$k])?>"></div><?php endforeach;?><button class="btn btn-primario">Buscar</button><a class="btn btn-secundario" href="<?=h(enlace(['vista'=>'movimientos']))?>">Limpiar</a></form>
<div class="cajero-acciones"><a class="btn btn-reporte" target="_blank" rel="noopener" href="<?=h(urlAplicacion('views/cliente/pdf.php?tipo=historial'))?>">PDF general</a><?php if($filtroValido):?><a class="btn btn-reporte" target="_blank" rel="noopener" href="<?=h(urlAplicacion('views/cliente/pdf.php?tipo=historial&'.http_build_query(['filtro_tipo'=>$params['tipo'],'cuenta'=>$params['cuenta'],'desde'=>$params['desde'],'hasta'=>$params['hasta']])) )?>">PDF filtrado</a><?php endif;?></div>
<p class="crud-resumen">Total de registros: <strong><?=h($d['total'])?></strong></p><div class="crud-tabla-responsive"><table class="crud-tabla"><thead><tr><?php foreach(['Fecha','Cuenta','Tipo','Monto','Saldo final','Cuenta relacionada','Referencia'] as $t):?><th><?=h($t)?></th><?php endforeach;?></tr></thead><tbody><?php foreach($d['filas'] as $m):?><tr><td><?=h($m['fecha'])?></td><td><?=h($m['numero_cuenta'])?></td><td><?=h(tipo($m['tipo']))?></td><td><?=h(dinero($m['monto']))?></td><td><?=h(dinero($m['saldo_resultante']))?></td><td><?=h($m['cuenta_relacionada']??'—')?></td><td><?=h($m['referencia'])?></td></tr><?php endforeach;?><?php if(!$d['filas']):?><tr><td colspan="7" class="crud-sin-resultados">No hay movimientos que coincidan con los filtros.</td></tr><?php endif;?></tbody></table></div><nav class="crud-paginacion-enlaces" aria-label="Paginación"><?php if($d['pagina']>1):?><a class="crud-pagina" href="<?=h(enlace(['vista'=>'movimientos','pagina'=>$d['pagina']-1]+$params))?>">Anterior</a><?php endif;?><span class="crud-pagina pagina-activa"><?=h($d['pagina'])?> / <?=h($d['paginas'])?></span><?php if($d['pagina']<$d['paginas']):?><a class="crud-pagina" href="<?=h(enlace(['vista'=>'movimientos','pagina'=>$d['pagina']+1]+$params))?>">Siguiente</a><?php endif;?></nav></section>
